import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A grade a person was given and the date it applies from (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFrom());
        }
    }

    /** A hold put on a person: from its from-date to its to-date (null: it does not end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(PersonHold hold) {
            return new HoldView(hold.getFrom(), hold.getTo());
        }
    }

    /** A person as the screen shows them, with the grade in force on the sheet's today and every
     *  grade they were given from the earliest, how many statements were taken for them and the
     *  last one's due-total and date (null when none was), and whether they are retired and from
     *  when (null when not), and the holds put on them in the order they were, and the ids of their patrons in the order
     *  they were named, and whether the signed-in user watches them, and their own terms (null for none). */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms) {
        public static PersonView of(Person person, List<PersonGrade> grades, LocalDate today,
                StatementSummary statements, List<PersonHold> holds, List<Long> patronIds, boolean watched) {
            return new PersonView(person.getId(), person.getName(), PersonGradeService.gradeOn(grades, today),
                    grades.stream().map(GradeView::of).toList(), person.getVersion(), statements.count(),
                    statements.lastDueTotal(), statements.lastDate(), person.isRetired(), person.getRetiredFrom(),
                    holds.stream().map(HoldView::of).toList(), patronIds, watched, person.getTerms());
        }
    }

    /** A person's fields: a name that is not blank, a grade of A, B or C, and their own terms in whole
     *  days (null for none). */
    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            @Min(0) @Max(36500) Integer terms) {
    }

    /** A person's fields as saved from an editor: the grade applies from its from-date (blank takes
     *  the sheet's today), their own terms in whole days (null for none), with the version of the person the editor loaded. */
    public record PersonUpdate(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Min(0) @Max(36500) Integer terms,
            @NotNull Long version) {
    }

    /** A retirement: the date the person is retired from (blank takes the sheet's today). */
    public record RetireRequest(LocalDate from) {
    }

    /** A hold: the date it runs from (blank takes the sheet's today) and an optional to-date. */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchRequest(@NotNull Boolean watched) {
    }

    /** A patron to name: the id of another person on the sheet. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final RollupService rollups;
    private final PersonGradeService grades;
    private final SheetService sheets;

    public PersonController(PersonService service, StatementService statements, RollupService rollups,
            PersonGradeService grades, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.rollups = rollups;
        this.grades = grades;
        this.sheets = sheets;
    }

    /** The sheet's people in the order they were added: as they stand now, or as they stood at the
     *  end of the screen's as-of date (those added by then, the date standing in for the sheet's today). */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = SignedInUser.HEADER, required = false) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        String sheet = sheetId.trim();
        LocalDate asOf = AsOf.parse(asOfHeader);
        Set<Long> watched = user == null ? Set.of() : service.watchedIds(sheet, SignedInUser.decode(user), asOf);
        Map<Long, StatementSummary> summaries = statements.summaries(sheet, asOf);
        Map<Long, List<Long>> patrons = service.patronIds(sheet, asOf);
        Map<Long, List<PersonGrade>> given = grades.bySheet(sheet, asOf);
        Map<Long, List<PersonHold>> holds = service.holds(sheet, asOf);
        LocalDate today = asOf != null ? asOf : sheets.today(sheet);
        return service.list(sheet, asOf).stream()
                .map(p -> PersonView.of(p, given.getOrDefault(p.getId(), List.of()), today,
                        summaries.getOrDefault(p.getId(), StatementSummary.NONE),
                        holds.getOrDefault(p.getId(), List.of()),
                        patrons.getOrDefault(p.getId(), List.of()), watched.contains(p.getId())))
                .toList();
    }

    /** Add a person to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PersonRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.add(sheet, by, request.name(),
                request.grade(), request.terms())), by);
    }

    /** Change a person's name and give them a grade from a date; refused when the person was saved since the editor loaded them. */
    @PutMapping("/{id}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PersonUpdate request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.update(sheet, by, id, request.version(),
                request.name(), request.grade(), request.gradeFrom(), request.terms())), by);
    }

    /** Retire a person from a date. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody RetireRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.retire(sheet, by, id, request.from())), by);
    }

    /** Put a hold on a person from a date to an optional to-date. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody HoldRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by,
                () -> service.hold(sheet, by, id, request.from(), request.to())), by);
    }

    /** Name another person on the sheet as a person's patron. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PatronRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(service.addPatron(sheet, by, id, request.patronId()), by);
    }

    /** Start or stop the signed-in user watching a person. */
    @PostMapping("/{id}/watch")
    public PersonView watch(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated WatchRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(service.watch(sheet, by, id, request.watched()), by);
    }

    /** A date that is not a real yyyy-mm-dd date, or a hold that ends before it starts, is refused. */
    @ExceptionHandler({HttpMessageNotReadableException.class, HoldRefusedException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** Someone else saved the person since the editor loaded them: the person as stored now. */
    @ExceptionHandler(StalePersonException.class)
    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
    public PersonView stale(StalePersonException e, HttpServletRequest request) {
        String user = request.getHeader(SignedInUser.HEADER);
        return withStatements(e.getCurrent(), user == null ? null : SignedInUser.decode(user));
    }

    private PersonView withStatements(Person person, String user) {
        return PersonView.of(person, grades.of(person.getId()), sheets.today(person.getSheetId()),
                statements.summary(person.getSheetId(), person.getId()), service.holds(person.getId()),
                service.patronIds(person.getId()), user != null && service.watches(person.getId(), user));
    }

    /** A save that raced another to the same version; the editor re-reads the person. */
    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)
    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
    public void raced() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** The name is already in use on the sheet, or the patron may not be named; a concurrent save is
     *  caught by the unique index. */
    @ExceptionHandler({NameInUseException.class, PatronRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameInUse() {
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import net.officefloor.hq.app.history.History;
import org.springframework.stereotype.Service;

/** The grades given to the people on a sheet, each in force from its from-date. */
@Service
public class PersonGradeService {

    /** Grades from the earliest: no from-date first, then by from-date. */
    private static final Comparator<PersonGrade> FROM_EARLIEST =
            Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));

    private final PersonGradeRepository grades;
    private final History history;

    public PersonGradeService(PersonGradeRepository grades, History history) {
        this.grades = grades;
        this.history = history;
    }

    /** A person's grades, from the earliest. */
    public List<PersonGrade> of(Long personId) {
        return grades.findByPersonId(personId).stream().sorted(FROM_EARLIEST).toList();
    }

    /** Each person's grades on the sheet, from the earliest, by person id. */
    public Map<Long, List<PersonGrade>> bySheet(String sheetId) {
        return grades.findBySheetId(sheetId).stream().sorted(FROM_EARLIEST)
                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
    }

    /** Each person's grades on the sheet as they stood at the end of a day, from the earliest, by
     *  person id (null: as they stand now). */
    public Map<Long, List<PersonGrade>> bySheet(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return bySheet(sheetId);
        }
        return bySheet(sheetId).keySet().stream().collect(Collectors.toMap(id -> id,
                id -> history.grades(id, asOf).stream().sorted(FROM_EARLIEST).toList()));
    }

    /** The person's grade in force on a date: the one whose from-date is the latest on or before it
     *  (the first grade applies from the beginning of time). */
    public String gradeOn(Long personId, LocalDate date) {
        return gradeOn(of(personId), date);
    }

    /** The person's grade in force on a date as their grades stood at the end of a day (null: as
     *  they stand now). */
    public String gradeOn(Long personId, LocalDate date, LocalDate asOf) {
        return gradeOn(asOf == null ? of(personId) : history.grades(personId, asOf), date);
    }

    /** The grade in force on a date among a person's grades; null when they have none. */
    public static String gradeOn(List<PersonGrade> theirs, LocalDate date) {
        return theirs.stream()
                .filter(g -> g.appliesOn(date))
                .max(FROM_EARLIEST)
                .map(PersonGrade::getGrade)
                .orElse(null);
    }

    /** Give a person a grade from a date (null: from the beginning of time), replacing the one they
     *  had from that date and keeping the others. */
    public PersonGrade give(Person person, String grade, LocalDate from) {
        Optional<PersonGrade> had = from == null
                ? grades.findByPersonIdAndFromIsNull(person.getId())
                : grades.findByPersonIdAndFrom(person.getId(), from);
        PersonGrade given = had
                .map(existing -> {
                    existing.setGrade(grade);
                    return existing;
                })
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), grade, from));
        return grades.saveAndFlush(given);
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonGradeService grades;
    private final PersonHoldRepository holds;
    private final PersonWatchRepository watches;
    private final SheetService sheets;
    private final EntityManager entityManager;
    private final History history;
    private final Audit audit;

    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonGradeService grades,
            PersonHoldRepository holds, PersonWatchRepository watches, SheetService sheets,
            EntityManager entityManager, History history, Audit audit) {
        this.history = history;
        this.people = people;
        this.watches = watches;
        this.patrons = patrons;
        this.grades = grades;
        this.holds = holds;
        this.entityManager = entityManager;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a person to the sheet; the grade they are given applies from the beginning of time. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        return add(sheetId, user, name, grade, null);
    }

    /** Add a person to the sheet with their own terms (null for none); the grade they are given
     *  applies from the beginning of time. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        LocalDate today = sheets.today(sheetId);
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, null);
        Person person = new Person(sheetId, trimmed, today);
        person.setTerms(terms);
        Person added = people.saveAndFlush(person);
        grades.give(added, grade, null);
        record("PERSON_ADDED", sheetId, user, added, grade, terms != null ? " terms=" + terms : "");
        return added;
    }

    /** Change a person's name, and give them the grade from a date (blank takes the sheet's today),
     *  keeping the grades already given, and set their own terms (null for none), from an editor that loaded the given version of them. A
     *  blank from-date with the grade in force on the sheet's today gives no grade. */
    @Transactional
    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        if (person.getVersion() != version) {
            throw new StalePersonException(person);
        }
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, id);
        person.setName(trimmed);
        Integer before = person.getTerms();
        person.setTerms(terms);
        LocalDate today = sheets.today(sheetId);
        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
            // A grade given changes the person, so an editor that loaded them before is stale.
            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
        }
        Person saved = people.saveAndFlush(person);
        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today),
                Objects.equals(before, terms) ? "" : " terms=" + (terms != null ? terms : ""));
        return saved;
    }

    /** Retire a person from a date; a missing date takes the sheet's today. */
    @Transactional
    public Person retire(String sheetId, String user, Long id, LocalDate from) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        person.setRetiredFrom(on);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + on);
        return saved;
    }

    /** Put a hold on a person from a date (a missing date takes the sheet's today) to an optional
     *  to-date, keeping the holds they have; refused when the to-date is before the from-date. */
    @Transactional
    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new HoldRefusedException("The hold's to-date " + to + " is before its from-date " + on);
        }
        holds.saveAndFlush(new PersonHold(sheetId, id, on, to, sheets.today(sheetId)));
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " from=" + on);
        return person;
    }

    /** Each person's holds on the sheet, in the order they were put on, by person id; a person with
     *  none is absent. */
    public Map<Long, List<PersonHold>> holds(String sheetId) {
        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonHold::getPersonId));
    }

    /** A person's holds, in the order they were put on. */
    public List<PersonHold> holds(Long personId) {
        return holds.findByPersonIdOrderByIdAsc(personId);
    }

    /** A person's holds as they stood at the end of a day: those put on while the sheet's today was
     *  on or before it, in the order they were put on. */
    public List<PersonHold> holdsAsOf(Long personId, LocalDate day) {
        return holds(personId).stream().filter(hold -> hold.madeAsOf(day)).toList();
    }

    /** Each person's patron ids on the sheet, in the order they were named, by person id; a person
     *  with none is absent. */
    public Map<Long, List<Long>> patronIds(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
    }

    /** Each person's patron ids on the sheet as they stood at the end of a day, in the order they were
     *  named, by person id (null: as they stand now); a person with none is absent. */
    public Map<Long, List<Long>> patronIds(String sheetId, LocalDate asOf) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(patron -> asOf == null || patron.madeAsOf(asOf))
                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
    }

    /** Each person's holds on the sheet as they stood at the end of a day, in the order they were put
     *  on, by person id (null: as they stand now); a person with none is absent. */
    public Map<Long, List<PersonHold>> holds(String sheetId, LocalDate asOf) {
        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(hold -> asOf == null || hold.madeAsOf(asOf))
                .collect(Collectors.groupingBy(PersonHold::getPersonId));
    }

    /** The ids of the people a user watched on the sheet at the end of a day (null: now). */
    public Set<Long> watchedIds(String sheetId, String user, LocalDate asOf) {
        Set<Long> now = watchedIds(sheetId, user);
        return asOf == null ? now : history.watched(sheetId, user, now, asOf);
    }

    /** The sheet's people as they stood at the end of a day, in the order they were added: those added
     *  by then, each with the name, own terms and retirement they had then (null: as they stand now). */
    public List<Person> list(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return list(sheetId);
        }
        Map<Long, History.PersonThen> then = history.people(sheetId, asOf);
        return list(sheetId).stream().filter(person -> person.onSheetAsOf(asOf)).map(person -> {
            History.PersonThen was = then.get(person.getId());
            return was == null ? person : person.asItWas(was.name(), was.terms(), was.retiredFrom());
        }).toList();
    }

    /** A person's patron ids, in the order they were named. */
    public List<Long> patronIds(Long personId) {
        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
    }

    /** Name another person on the sheet as a person's patron; refused for the person themselves and
     *  for someone already their patron. */
    @Transactional
    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
        if (person.getId().equals(patron.getId())) {
            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
        }
        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId(), sheets.today(sheetId)));
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return person;
    }

    /** Start or stop a user watching a person; a person already in that state is left as they are,
     *  writing nothing. */
    @Transactional
    public Person watch(String sheetId, String user, Long id, boolean on) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        var existing = watches.findByPersonIdAndUser(id, user);
        if (on && existing.isEmpty()) {
            watches.saveAndFlush(new PersonWatch(sheetId, id, user));
            history.watchSet(sheetId, id, user, true);
            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
        } else if (!on && existing.isPresent()) {
            watches.delete(existing.get());
            watches.flush();
            history.watchSet(sheetId, id, user, false);
            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
        }
        return person;
    }

    /** The ids of the people a user watches on the sheet. */
    public Set<Long> watchedIds(String sheetId, String user) {
        return watches.findBySheetIdAndUser(sheetId, user).stream().map(PersonWatch::getPersonId)
                .collect(Collectors.toSet());
    }

    /** Whether a user watches a person. */
    public boolean watches(Long personId, String user) {
        return watches.findByPersonIdAndUser(personId, user).isPresent();
    }

    /** A person's watchers, in the order they started watching. */
    public List<String> watchers(Long personId) {
        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUser).toList();
    }

    private void record(String event, String sheetId, String user, Person person, String grade, String terms) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + grade + terms);
    }

    private void requireFreeName(String sheetId, String name, Long exceptId) {
        if (people.nameInUse(sheetId, name, exceptId)) {
            throw new NameInUseException(name);
        }
    }
}

