package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.setting.PermissionRefusedException;
import net.officefloor.hq.app.setting.SettingService;
import java.util.Set;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;

/** Settles a selection of claims together. */
@Service
public class BulkSettleService {

    /** What a bulk settle did: the claims it settled (SETTLED, or PENDING a steward's approval), in
     *  the order it settled them, and how many of the selected claims it refused. */
    public record Result(List<Claim> settled, int refused) {
    }

    private final ClaimListOrder order;
    private final ClaimService service;
    private final RollupService rollups;
    private final SettingService settings;
    private final SheetService sheets;

    public BulkSettleService(ClaimListOrder order, ClaimService service, RollupService rollups, SettingService settings,
            SheetService sheets) {
        this.order = order;
        this.service = service;
        this.rollups = rollups;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Settle each selected claim that can be settled, in list order (people in the order they were
     *  added, each person's claims newest first), by exactly the rules of settling one: a clerk's
     *  claim above the clerk limit goes PENDING and counts as settled. Each that cannot, or is not
     *  on the sheet, is refused and left as it is. Each claim is settled on its own, so a refused
     *  one writes nothing. */
    public Result settle(String sheetId, String user, Set<Long> ids) {
        List<Claim> settled = new ArrayList<>();
        if (settings.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer, or anyone on an archived sheet, changes nothing: every selected claim is refused.
            return new Result(settled, ids.size());
        }
        for (Claim claim : order.selected(sheetId, ids)) {
            try {
                settled.add(rollups.track(sheetId, user, () -> service.changeStatus(sheetId, user,
                        claim.getPersonId(), claim.getId(), ClaimStatus.SETTLED)));
            } catch (StatusChangeRefusedException | PermissionRefusedException | OwnClaimSettleRefusedException | ProofRequiredException | PeriodClosedException
                    | NoSuchElementException refused) {
                // Left as it is: its change rolled back with its own transaction.
            }
        }
        return new Result(settled, ids.size() - settled.size());
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeService;
import net.officefloor.hq.app.person.PersonHold;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The figures a sheet rolls up to: each person's claimed, due-total and overdue-total, and the sheet's totals. A
 *  change made through {@link #track} is followed in the audit by a line for each person whose
 *  figures it moved, then one for the sheet's totals when they moved. */
@Service
public class RollupService {

    /** Written for a due-total that has no rate to work from. */
    private static final String NO_RATE = "n/a";

    private static final BigDecimal NONE = BigDecimal.ZERO.setScale(2);

    /** A person's figures; due is null when it has no rate to work from. */
    private record Figures(String name, BigDecimal claimed, BigDecimal due, BigDecimal overdue) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(due, other.due)
                    && overdue.compareTo(other.overdue) == 0;
        }
    }

    /** The sheet's figures: each person's, by id in the order they were added, and the totals. */
    private record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateService rates;
    private final PersonGradeService grades;
    private final PersonService personService;
    private final SheetService sheets;
    private final SettingService settings;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, ClaimService claimService,
            RateService rates, PersonGradeService grades, PersonService personService, SheetService sheets,
            SettingService settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.grades = grades;
        this.personService = personService;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Make a change to the sheet, then record in the audit the figures it moved. The sheet is held
     *  locked throughout, so a change made at the same moment waits and the figures are its own. */
    @Transactional
    public <T> T track(String sheetId, String user, Supplier<T> change) {
        sheets.lock(sheetId);
        Rollup before = rollup(sheetId);
        T result = change.get();
        Rollup after = rollup(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + text(figures.due())
                        + " overdue-total=" + figures.overdue().toPlainString());
            }
        });
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0
                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString()
                    + " overdue-total=" + after.overdueTotal().toPlainString());
        }
        return result;
    }

    private Rollup rollup(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        Map<Long, LocalDate> retiredFrom = new HashMap<>();
        sheetPeople.forEach(person -> retiredFrom.put(person.getId(), person.getRetiredFrom()));
        Map<Long, List<Claim>> counted = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(claim -> claim.countsLive(holds.getOrDefault(claim.getPersonId(), List.of()),
                        retiredFrom.get(claim.getPersonId()), today))
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = NONE;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : sheetPeople) {
            Figures f = figuresOf(sheetId, today, person, counted.getOrDefault(person.getId(), List.of()));
            figures.put(person.getId(), f);
            claimedTotal = claimedTotal.add(f.claimed());
            if (f.due() != null) {
                dues.add(f.due());
            }
            overdues.add(f.overdue());
        }
        return new Rollup(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are
     *  three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(NONE, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
    }

    /** A person's figures from their claims that count: the sum of their amounts, and the sum of the
     *  figures they show, or none when the grade in force on the sheet's today has no rate in force
     *  then and no claim of theirs shows a figure; the sum is held to the sheet's cap. The overdue-total
     *  sums the dues of those that are OPEN or PENDING with a due-by before the sheet's today. */
    private Figures figuresOf(String sheetId, LocalDate today, Person person, List<Claim> counted) {
        BigDecimal claimed = NONE;
        BigDecimal due = NONE;
        BigDecimal overdue = NONE;
        boolean anyFigure = false;
        for (Claim claim : counted) {
            claimed = claimed.add(claim.getAmount());
            BigDecimal figure = claimService.dueOf(sheetId, person, claim);
            if (figure != null) {
                due = due.add(figure);
                if (claim.getStatus().isOpen() && claim.getDueBy().isBefore(today)) {
                    overdue = overdue.add(figure);
                }
            }
            anyFigure |= figure != null;
        }
        boolean hasRate = rates.rateOn(sheetId, grades.gradeOn(person.getId(), today), today).isPresent();
        return new Figures(person.getName(), claimed, hasRate || anyFigure ? settings.capped(sheetId, due) : null,
                overdue);
    }

    private static String text(BigDecimal due) {
        return due == null ? NO_RATE : due.toPlainString();
    }
}
