649	  /** Retire a person from the typed date (blank takes the sheet's today); their row then shows it,
650	   *  or leaves the list while retired people are not shown. */
651	  protected async retire(person: Person): Promise<void> {
652	    this.rowError.set(null);
653	    const sheet = this.session.sheetId();
654	    if (!sheet) return;
655	    const from = (this.retireDates()[person.id] ?? '').trim() || null;
656	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`;
657	    try {
658	      const saved = await firstValueFrom(this.http.post<Person>(url, { from }));
659	      if (this.session.sheetId() !== sheet) return;
660	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
661	      this.retireDates.update((dates) => ({ ...dates, [person.id]: '' }));
662	    } catch {
663	      this.rowError.set({ id: person.id, message: `${person.name} could not be retired.` });
664	    }
665	  }
