673	  protected async addPatron(person: Person): Promise<void> {
674	    this.rowError.set(null);
675	    const sheet = this.session.sheetId();
676	    if (!sheet) return;
677	    const refused = (message: string) =>
678	      this.rowError.set({ id: person.id, message, testId: 'person-patron-error' });
679	    const chosen = this.patronChoices()[person.id] ?? '';
680	    if (!chosen) {
681	      refused('Choose a patron to add.');
682	      return;
683	    }
684	    const patronId = Number(chosen);
685	    const patron = this.people().find((p) => p.id === patronId);
686	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons`;
687	    try {
688	      const saved = await firstValueFrom(this.http.post<Person>(url, { patronId }));
689	      if (this.session.sheetId() !== sheet) return;
690	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
691	      this.patronChoices.update((choices) => ({ ...choices, [person.id]: '' }));
692	    } catch {
693	      refused(
694	        patronId === person.id
695	          ? `${person.name} cannot be their own patron.`
696	          : `${patron?.name ?? 'That person'} could not be added as a patron of ${person.name}.`,
697	      );
698	    }
699	  }
