701	  /** A person's patrons' names, sorted, comma and space separated. */
702	  protected patronsOf(person: Person): string {
703	    const names = new Map(this.people().map((p) => [p.id, p.name]));
704	    return person.patronIds
705	      .map((id) => names.get(id))
706	      .filter((name): name is string => name !== undefined)
707	      .sort((a, b) => a.localeCompare(b))
708	      .join(', ');
709	  }
