711	  /** A person's patrons' settled figures added up: the due frozen on each of their SETTLED claims dated
712	   *  within the 90 days up to and including the sheet's today; 0.00 with none. */
713	  protected backingOf(person: Person): string {
714	    const today = this.session.today();
715	    if (today === null) return money(0);
716	    const since = plusDays(today, -89);
717	    const byPerson = this.claimsByPerson();
718	    return money(
719	      person.patronIds.reduce(
720	        (sum, id) =>
721	          (byPerson.get(id) ?? [])
722	            .filter((c) => c.status === 'SETTLED' && c.settledDue !== null && since <= c.date && c.date <= today)
723	            .reduce((total, c) => total + cents(c.settledDue ?? '0'), sum),
724	        0,
725	      ),
726	    );
727	  }
