772	  /** Download everyone, retired people included, in list order as CSV: name, the grade in force
773	   *  on the sheet's today, the retired-from date (or nothing) and the due-total as shown. */
774	  protected exportCsv(): void {
775	    const field = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
776	    const lines = [
777	      'name,grade,retired-from,due-total',
778	      ...this.people().map((p) =>
779	        [p.name, this.gradeOf(p), p.retiredFrom ?? '', this.dueBy(p)].map(field).join(','),
780	      ),
781	    ];
782	    const blob = new Blob([lines.map((l) => l + '\n').join('')], { type: 'text/csv' });
783	    const url = URL.createObjectURL(blob);
784	    const link = document.createElement('a');
785	    link.href = url;
786	    link.download = `people-${this.session.sheetId() ?? 'sheet'}.csv`;
787	    link.click();
788	    setTimeout(() => URL.revokeObjectURL(url));
789	  }
